//! Differential ratchet for
//! `src/engine/battleScriptSetdestinybondOpcode.ts`. Expected projected
//! results and the exact error are generated by invoking the canonical
//! TypeScript opcode handler; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-setdestinybond-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setdestinybond::{
    apply_battle_script_setdestinybond, BattleScriptSetdestinybondBattlerState,
    BattleScriptSetdestinybondRoles, BattleScriptSetdestinybondRules,
    BATTLE_SCRIPT_SETDESTINYBOND_BATTLERS, BATTLE_SCRIPT_SETDESTINYBOND_BATTLER_COUNT,
    BATTLE_SCRIPT_STATUS2_DESTINY_BOND,
};
use factory_core::battle_script_setdestinybond_vectors_gen::{
    BattleScriptSetdestinybondVectorCase, BattleScriptSetdestinybondVectorState,
    BATTLE_SCRIPT_SETDESTINYBOND_BATTLER_DOMAIN, BATTLE_SCRIPT_SETDESTINYBOND_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETDESTINYBOND_CASES, BATTLE_SCRIPT_SETDESTINYBOND_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETDESTINYBOND_DESTINY_BOND_INPUT_DOMAIN,
    BATTLE_SCRIPT_SETDESTINYBOND_DOMAIN_CENSUS, BATTLE_SCRIPT_SETDESTINYBOND_STATUS2_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETDESTINYBOND_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSetdestinybondVectorState) -> BattleScriptSetdestinybondRules {
    BattleScriptSetdestinybondRules {
        battlers: value
            .status2
            .map(|status2| BattleScriptSetdestinybondBattlerState { status2 }),
        selector_roles: BattleScriptSetdestinybondRoles { attacker: value.attacker },
    }
}

fn vector_state(value: BattleScriptSetdestinybondRules) -> BattleScriptSetdestinybondVectorState {
    BattleScriptSetdestinybondVectorState {
        status2: value.battlers.map(|battler| battler.status2),
        attacker: value.selector_roles.attacker,
    }
}

#[test]
fn complete_projected_outputs_and_exact_missing_role_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETDESTINYBOND_CASES.len(), 25);
    for (case_index, case) in BATTLE_SCRIPT_SETDESTINYBOND_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetdestinybondVectorCase) {
    let input = rules(case.initial);
    let before = input;
    match (
        apply_battle_script_setdestinybond(&input),
        case.expected,
        case.expected_error,
    ) {
        (Ok(actual), Some(expected), None) => {
            let attacker = before.selector_roles.attacker.unwrap_or_else(|| {
                panic!(
                    "case {case_index} {}: success vector has no attacker",
                    case.label
                )
            });
            let attacker_index = attacker.index();

            assert_eq!(input, before, "case {case_index} {}: native transformation mutated input", case.label);
            assert_eq!(
                vector_state(actual),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
            assert_eq!(
                actual.selector_roles,
                before.selector_roles,
                "case {case_index} {}: changed selector role binding",
                case.label,
            );
            for battler in BATTLE_SCRIPT_SETDESTINYBOND_BATTLERS {
                if battler != attacker {
                    assert_eq!(
                        actual.battlers[battler.index()],
                        before.battlers[battler.index()],
                        "case {case_index} {}: changed non-attacker battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            assert_eq!(
                actual.battlers[attacker_index].status2,
                before.battlers[attacker_index].status2 | BATTLE_SCRIPT_STATUS2_DESTINY_BOND,
                "case {case_index} {}: did not OR the destiny-bond bit into the attacker",
                case.label,
            );
            assert_eq!(
                actual.battlers[attacker_index].status2 & !BATTLE_SCRIPT_STATUS2_DESTINY_BOND,
                before.battlers[attacker_index].status2 & !BATTLE_SCRIPT_STATUS2_DESTINY_BOND,
                "case {case_index} {}: changed attacker status2 unrelated bits",
                case.label,
            );

            let repeated = apply_battle_script_setdestinybond(&actual).unwrap_or_else(|error| {
                panic!(
                    "case {case_index} {}: second application errored: {error}",
                    case.label
                )
            });
            assert_eq!(
                repeated,
                actual,
                "case {case_index} {}: setting destiny bond is not idempotent",
                case.label,
            );
        }
        (Err(error), None, Some(expected_error)) => {
            assert_eq!(input, before, "case {case_index} {}: failed transformation mutated input", case.label);
            assert_eq!(
                error.to_string(),
                expected_error,
                "case {case_index} {}: exact missing-attacker error",
                case.label,
            );
        }
        (result, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: result={result:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

#[test]
fn matrix_covers_all_attackers_clear_and_set_inputs_and_u32_edges() {
    let matrix = BATTLE_SCRIPT_SETDESTINYBOND_CASES
        .iter()
        .filter(|case| case.category == "attacker-status2-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 8);

    let matrix_domain = matrix
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("matrix case {} is missing attacker", case.label));
            (attacker.as_u8(), case.initial.status2[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(
        matrix_domain,
        BTreeSet::from([
            (0, 0x0000_0000),
            (0, BATTLE_SCRIPT_STATUS2_DESTINY_BOND),
            (1, 0x0000_0000),
            (1, BATTLE_SCRIPT_STATUS2_DESTINY_BOND),
            (2, 0x0000_0000),
            (2, BATTLE_SCRIPT_STATUS2_DESTINY_BOND),
            (3, 0x0000_0000),
            (3, BATTLE_SCRIPT_STATUS2_DESTINY_BOND),
        ]),
        "each attacker must have both initially-clear and already-set inputs",
    );

    let edges = BATTLE_SCRIPT_SETDESTINYBOND_CASES
        .iter()
        .filter(|case| case.category == "u32-status2-edge-matrix")
        .collect::<Vec<_>>();
    assert_eq!(edges.len(), 16);
    let edge_domain = edges
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("edge case {} is missing attacker", case.label));
            (attacker.as_u8(), case.initial.status2[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected_edges = BATTLE_SCRIPT_SETDESTINYBOND_STATUS2_EDGE_DOMAIN
        .into_iter()
        .flat_map(|status2| (0..4).map(move |attacker| (attacker, status2)))
        .collect::<BTreeSet<_>>();
    assert_eq!(
        edge_domain, expected_edges,
        "every u32 edge must occur for all four attackers"
    );
}

#[test]
fn fixed_four_slot_domain_and_source_constants_are_retained() {
    assert_eq!(BATTLE_SCRIPT_SETDESTINYBOND_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETDESTINYBOND_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETDESTINYBOND_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_DESTINY_BOND_INPUT_DOMAIN,
        [0x0000_0000, 0x0200_0000],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_STATUS2_EDGE_DOMAIN,
        [0x0000_0000, 0xffff_ffff, 0x8000_0000, 0x0100_0001],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS2_DESTINY_BOND, 0x0200_0000);
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("optional-attacker-role-values", 5),
            ("status2-u32-values", 4_294_967_296),
            ("status2-edge-values", 4),
            ("destiny-bond-clear-set-inputs", 2),
            ("typed-missing-role-combinations", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_CATEGORY_CENSUS,
        [
            ("attacker-status2-matrix", 8),
            ("missing-attacker-role", 1),
            ("u32-status2-edge-matrix", 16),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_BRANCH_CENSUS,
        [
            ("missing-attacker-role", 1),
            ("set-attacker-destiny-bond", 24)
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETDESTINYBOND_VECTOR_CORPUS_SHA256,
        "b024fb02d948ecbf7e5417738eaf53704d811466b6f069ef915e6aa263e73315",
    );
}
